INSERT INTO recipes (recipe_id, category_id, dessert_name, description, photo_url, base_diameter, instructions) VALUES 
(1, 4, 'Класична Паска', 'Ароматна здобна паска з родзинками та цукатами.', 'img/paska_classic.jpg', 15, '1. Приготуйте опару з дріжджів, теплого молока та частини борошна.\n2. Додайте збиті яйця, жовтки, цукор та розтоплене масло.\n3. Вмішайте родзинки та вимісіть тісто.\n4. Випікайте при 180°C до сухої палички.'),
(2, 4, 'Сирна Паска (без випічки)', 'Ніжний сирний десерт з вершками та горіхами.', 'img/paska_curd.jpg', 12, '1. Перетріть кисломолочний сир через дрібне сито двічі.\n2. Збийте жирні вершки з пудрою до щільності.\n3. Додайте розм''якшене масло, цукати та горіхи, обережно перемішайте.\n4. Покладіть масу у пасочницю під гніт у холодильник на ніч.'),
(3, 4, 'Шоколадна Паска', 'Сучасна версія традиційної паски з насиченим смаком шоколаду.', 'img/paska_choc.jpg', 14, '1. Розчиніть какао в теплому молоці та додайте в основне здобне тісто.\n2. Перед вистоюванням вмішайте всередину шоколадні краплі.\n3. Випікайте до готовності.\n4. Повністю охолодіть і полийте розтопленою шоколадною глазур''ю.'),
(4, 4, 'Панеттоне', 'Італійська святкова випічка з великою кількістю цукатів.', 'img/panettone.jpg', 16, '1. Зробіть опару і залиште для тривалого бродіння (мінімум 12 годин).\n2. Додайте велику кількість вершкового масла та жовтків, вимішуйте до "глютенового вікна".\n3. Вмішайте цукати.\n4. Після випікання обов''язково охолоджуйте догори ногами на шпажках.'),
(5, 4, 'Великодні Зайчики', 'Медове печиво у формі зайчиків для дітей.', 'img/bunnies.jpg', 10, '1. Нагрійте мед з маслом та спеціями.\n2. Замісіть еластичне медове тісто з содою та борошном.\n3. Розкачайте тісто та виріжте фігурки зайчиків.\n4. Випікайте 8-10 хвилин і розпишіть білковою глазур''ю.'),
(6, 4, 'Лимонний Великодній Кекс', 'Легкий кекс з цедрою та лимонним курдом.', 'img/lemon_cake.jpg', 20, '1. Збийте м''яке масло з цукром та натертою цедрою до побіління.\n2. По одному введіть яйця та лимонний сік.\n3. Вмішайте борошно з розпушувачем.\n4. Випікайте 45 хвилин при 170°C.'),
(7, 4, 'Сирник "Сльози Ангела"', 'Класичний сирник з ніжною меренгою зверху.', 'img/angel_tears.jpg', 22, '1. Замісіть пісочне тісто та викладіть його як основу.\n2. Збийте сирну масу з жовтками та сметаною, вилийте на основу і запікайте.\n3. За 10-15 хвилин до кінця випікання викладіть зверху збиті з пудрою білки.\n4. Охолоджуйте в духовці, щоб з''явилися "сльозинки" (крапельки карамелі).'),
(8, 4, 'Маковий рулет святковий', 'Традиційний рулет з великою кількістю макової начинки.', 'img/poppy_roll.jpg', 25, '1. Запарьте мак окропом, злийте воду та перетріть його з цукром і білком.\n2. Розкачайте тонкий пласт дріжджового тіста.\n3. Викладіть макову начинку, відступаючи від країв, і щільно скрутіть рулет.\n4. Випікайте при 180°C близько 35-40 хвилин.'),
(9, 4, 'Морквяний торт з горіхами', 'Пряний десерт, який ідеально підходить до весняного свята.', 'img/carrot_cake.jpg', 20, '1. Натріть моркву на дуже дрібній тертці.\n2. Змішайте збиті з цукром яйця, олію, борошно, горіхи та корицю.\n3. Випікайте коржі при 180°C.\n4. Перемажте охолоджені коржі кремом із збитого маскарпоне з пудрою.'),
(10, 4, 'Шоколадні "Гнізда"', 'Десерт без випічки з пластівців та шоколаду.', 'img/nests.jpg', 8, '1. Розтопіть темний шоколад на водяній бані разом з маслом.\n2. Обережно вмішайте кукурудзяні пластівці, щоб вони повністю покрилися шоколадом.\n3. Сформуйте невеликі гнізда на пергаменті.\n4. Охолодіть і покладіть всередину шоколадні яйця або драже.'),
(11, 1, 'Тірамісу Класичне', 'Легендарний італійський десерт на основі кави.', 'img/tiramisu.jpg', 20, '1. Заваріть міцний еспресо та дайте йому охолонути.\n2. Збийте маскарпоне з жовтками та цукром до густого крему.\n3. Швидко занурюйте печиво савоярді в каву та викладайте у форму шарами, чергуючи з кремом.\n4. Перед подачею посипте какао-порошком.'),
(12, 1, 'Наполеон домашній', 'Багатошаровий торт з ніжним заварним кремом.', 'img/napoleon.jpg', 24, '1. Посічіть холодне масло з борошном, додайте крижану воду і замісіть тісто. Охолодіть.\n2. Розкачайте і випечіть 10-12 дуже тонких коржів при 200°C.\n3. Зваріть заварний крем на молоці та жовтках.\n4. Перемажте коржі гарячим кремом і залиште торт настоюватися мінімум 12 годин.'),
(13, 1, 'Медовик зі сметаною', 'Ароматні медові коржі та кислинка сметанного крему.', 'img/medovik.jpg', 22, '1. Розтопіть мед, масло і цукор на водяній бані. Додайте соду (маса має спінитися).\n2. Вмішайте яйця і борошно, замісіть тісто.\n3. Розкачайте тонкі коржі і випікайте по 3-4 хвилини.\n4. Перемажте коржі кремом із жирної сметани, збитої з пудрою.'),
(14, 1, 'Празький торт', 'Шоколадний торт з насиченим масляним кремом.', 'img/prague.jpg', 20, '1. Збийте яйця з цукром, обережно вмішайте борошно, какао та розтоплене масло. Випечіть бісквіт.\n2. Для крему заваріть жовток з водою і згущеним молоком, охолодіть і збийте з маслом та какао.\n3. Розріжте бісквіт, промажте кремом.\n4. Обмажте торт абрикосовим джемом і залийте шоколадною глазур''ю.'),
(15, 1, 'Чізкейк Нью-Йорк', 'Класичний запечений чізкейк з вершкового сиру.', 'img/ny_cheesecake.jpg', 22, '1. Подрібніть пісочне печиво в крихту, змішайте з розтопленим маслом і утрамбуйте на дно форми.\n2. Крем-сир перемішайте (не збивайте!) з цукром, яйцями та вершками.\n3. Вилийте начинку на основу.\n4. Випікайте на водяній бані при 130°C близько 1.5 години. Охолоджуйте в духовці.'),
(16, 1, 'Червоний оксамит', 'Яскраво-червоні коржі з легким присмаком какао.', 'img/red_velvet.jpg', 18, '1. Змішайте кефір, олію, яйця та харчовий червоний барвник.\n2. Додайте сухі інгредієнти: борошно, трохи какао, цукор і соду.\n3. Випечіть коржі при 170°C.\n4. Перемажте торт стабільним кремом на основі крем-сиру та вершкового масла.'),
(17, 1, 'Три шоколади', 'Мусовий торт з трьох видів шоколаду.', 'img/three_choc.jpg', 18, '1. Спечіть тонкий шоколадний бісквіт для основи.\n2. Зробіть заварну базу на жовтках, розділіть на три частини і додайте в кожну різний шоколад та желатин.\n3. Вмішайте збиті вершки в кожен мус.\n4. Заливайте муси у кільце почергово, чекаючи застигання кожного шару в морозилці.'),
(18, 1, 'Естерхазі', 'Мигдально-фундучний торт без борошна.', 'img/esterhazy.jpg', 20, '1. Збийте білки з цукром до міцних піків, обережно вмішайте мелені горіхи.\n2. Намалюйте кола на пергаменті та випечіть 5-6 горіхових коржів.\n3. Зваріть заварний крем і збийте його з вершковим маслом.\n4. Перемажте коржі, а зверху намалюйте фірмову шоколадну павутинку.'),
(19, 1, 'Торт "Захер"', 'Австрійський шоколадний торт з абрикосовим конфітюром.', 'img/sacher.jpg', 20, '1. Збийте масло з шоколадом, введіть жовтки. Окремо збийте білки з цукром.\n2. З''єднайте маси з борошном і випечіть щільний шоколадний бісквіт.\n3. Розріжте бісквіт і рясно змажте підігрітим абрикосовим джемом (всередині і зовні).\n4. Покрийте торт глазур''ю з чорного шоколаду та вершків.'),
(20, 1, 'Меренговий рулет з ягодами', 'Повітряний десерт, що тане у роті.', 'img/meringue_roll.jpg', 25, '1. Збийте білки з пудрою до стійких піків, додайте лимонний сік та крохмаль.\n2. Розподіліть масу по пергаменту і випікайте при 150°C близько 20-25 хвилин до скоринки.\n3. Переверніть і охолодіть.\n4. Змажте кремом (маскарпоне + вершки), викладіть ягоди і обережно згорніть у рулет.'),
(21, 1, 'Пташине молоко', 'Ніжне суфле на агар-агарі в шоколаді.', 'img/bird_milk.jpg', 20, '1. Випечіть тонкий і щільний бісквіт для основи.\n2. Зваріть сироп з водою, цукром та агар-агаром до 110°C.\n3. Збийте білки і тонкою цівкою влийте гарячий сироп. Вмішайте збите масло зі згущеним молоком.\n4. Вилийте суфле на бісквіт, охолодіть і залийте шоколадною глазур''ю.'),
(22, 1, 'Торт "Павлова"', 'Легка меренга з хрусткою скоринкою та м''якою серединою.', 'img/pavlova.jpg', 15, '1. Збийте білки з цукром до глянцю, додайте оцет та кукурудзяний крохмаль.\n2. Сформуйте на пергаменті гніздо з високими бортами.\n3. Сушіть у духовці при 100°C близько 1.5-2 годин.\n4. Перед самою подачею наповніть збитими вершками без цукру та великою кількістю ягід.'),
(23, 1, 'Шварцвальдський торт', 'Шоколадний торт з вишнею та збитими вершками.', 'img/black_forest.jpg', 22, '1. Спечіть класичний шоколадний бісквіт і розріжте на 3 коржі.\n2. Проваріть вишню з цукром і крохмалем для начинки. Просочіть коржі вишневим сиропом.\n3. Збийте жирні вершки з пудрою.\n4. Зберіть торт: корж, вершки, вишня. Зверху прикрасьте шоколадною стружкою.'),
(24, 1, 'Торт "Рафаелло"', 'Ніжний кокосовий торт з мигдалем.', 'img/raffaello_cake.jpg', 18, '1. Випечіть пишний бісквіт з додаванням мигдального борошна.\n2. Для крему розтопіть білий шоколад у вершках, охолодіть і збийте з маскарпоне.\n3. Додайте в крем кокосову стружку та подрібнений бланшований мигдаль.\n4. Перемажте коржі та обсипте весь торт кокосом.'),
(25, 1, 'Торт "Опера"', 'Класика французького кондитерського мистецтва.', 'img/opera.jpg', 15, '1. Випечіть дуже тонкі мигдальні бісквіти "Джоконда".\n2. Приготуйте масляно-кавовий крем на жовтках та шоколадний ганаш.\n3. Рясно просочіть кожен корж кавовим сиропом.\n4. Зберіть торт, чергуючи дуже тонкі шари бісквіта, кавового крему та ганаша.'),
(26, 2, 'ПП Брауні', 'Шоколадний десерт на основі банана та какао без цукру.', 'img/pp_brownie.jpg', 15, '1. Розімніть стиглі банани виделкою в пюре.\n2. Додайте яйця, какао, розпушувач та трохи олії. Перемішайте до однорідності.\n3. Вилийте у невелику форму.\n4. Випікайте при 180°C близько 20 хвилин. Десерт має залишитися злегка вологим всередині.'),
(27, 2, 'Чіа-пудинг з манго', 'Корисний сніданок або легкий десерт.', 'img/chia.jpg', 10, '1. Залийте насіння чіа молоком, додайте краплю меду, добре перемішайте.\n2. Залиште в холодильнику на 2-3 години або на ніч, щоб насіння набрякло.\n3. Зробіть пюре зі свіжого манго у блендері.\n4. Викладіть у склянку шарами: чіа-пудинг і мангове пюре.'),
(28, 2, 'Вівсяне печиво з яблуком', 'Без борошна та цукру, лише користь.', 'img/oat_cookie.jpg', 10, '1. Натріть солодке яблуко на тертці.\n2. Змішайте яблуко з вівсяними пластівцями, яйцем та подрібненими горіхами.\n3. Дайте масі постояти 15 хвилин, щоб пластівці розм''якшилися.\n4. Сформуйте печиво і випікайте 15 хвилин при 180°C.'),
(29, 2, 'Кокосові цукерки', 'Домашні цукерки на кшталт "Баунті" без цукру.', 'img/coco_candies.jpg', 5, '1. Змішайте кокосову стружку з густими вершками та краплею меду до липкої маси.\n2. Сформуйте невеликі батончики і покладіть у морозилку на 30 хвилин.\n3. Розтопіть чорний шоколад (від 75%).\n4. Занурте кожен батончик у шоколад і викладіть на пергамент застигати.'),
(30, 2, 'Сирна запіканка з курагою', 'Класична запіканка на стевії.', 'img/curd_pp.jpg', 20, '1. Перебийте сир блендером разом з яйцями, сметаною та стевією до кремового стану.\n2. Додайте кукурудзяний крохмаль і добре перемішайте.\n3. Наріжте курагу дрібними кубиками і вмішайте в масу.\n4. Випікайте у силіконовій формі 40 хвилин при 170°C.'),
(31, 2, 'Банановий хліб з горіхами', 'Ароматний кекс без доданого цукру.', 'img/banana_bread.jpg', 18, '1. Розімніть дуже стиглі (з чорними крапками) банани в пюре.\n2. Змішайте з яйцями, олією та борошном із розпушувачем.\n3. Додайте січені волоські горіхи.\n4. Випікайте у формі для кексу при 180°C близько 45-50 хвилин.'),
(32, 2, 'Морквяні мафіни ПП', 'Здорові мафіни з горіхами та родзинками.', 'img/carrot_muffin.jpg', 8, '1. Натріть моркву на дрібній тертці.\n2. Змішайте вівсяне борошно, моркву, яйця, кефір, розпушувач та мед.\n3. Вмішайте попередньо замочені родзинки.\n4. Розкладіть по формочках для мафінів і випікайте 25 хвилин.'),
(33, 2, 'Ягідний сорбет', 'Заморожений десерт з чистих ягід.', 'img/sorbet.jpg', 10, '1. Візьміть сильно заморожені ягоди (полуниця, малина).\n2. Покладіть їх у потужний блендер, додайте трохи теплої води, лимонний сік та мед.\n3. Збийте до однорідної густої маси.\n4. Подавайте одразу або поставте в морозилку на 30 хвилин для більшої щільності.'),
(34, 2, 'Авокадо-шоколадний мус', 'Кремовий десерт зі здоровими жирами.', 'img/avocado_mousse.jpg', 10, '1. Почистіть стигле м''яке авокадо і видаліть кісточку.\n2. Покладіть у блендер авокадо, какао-порошок, молоко та мед.\n3. Перебийте масу до ідеально гладкого, шовковистого кремового стану.\n4. Розкладіть по креманках і охолодіть перед подачею.'),
(35, 2, 'Яблука запечені з медом', 'Найпростіший та найкорисніший десерт.', 'img/baked_apples.jpg', 12, '1. Помийте яблука і обережно виріжте серцевину, не прорізаючи яблуко наскрізь.\n2. Змішайте подрібнені горіхи з родзинками.\n3. Наповніть серединку яблук цією сумішшю і полийте медом.\n4. Запікайте 20-25 хвилин при 180°C до м''якості яблук.'),
(36, 3, 'Макаруни асорті', 'Французьке печиво на мигдальному борошні.', 'img/macarons.jpg', 5, '1. Змішайте мигдальне борошно з пудрою і просійте.\n2. Збийте білки з цукром у меренгу, обережно вмішайте суху суміш (зробіть макаронаж).\n3. Відсадіть кружальця на килимок і дайте їм підсохнути 30 хвилин до утворення плівки.\n4. Випікайте при 140°C, після охолодження з''єднайте половинки ганашем.'),
(37, 5, 'Еклери ванільні', 'Заварне тісто з ніжним кремом.', 'img/eclairs.jpg', 12, '1. Доведіть воду з молоком і маслом до кипіння, всипте борошно і заваріть тісто.\n2. Поступово вмішайте яйця до отримання правильної консистенції.\n3. Відсадіть смужки тіста і випікайте без відкривання дверцят духовки.\n4. Наповніть охолоджені еклери заварним кремом і покрийте помадкою.'),
(38, 3, 'Кантучіні', 'Сухе італійське печиво з цілим мигдалем.', 'img/cantuccini.jpg', 8, '1. Змішайте борошно, цукор, розпушувач, яйця та цедру.\n2. Вмішайте в тісто цілий сирий мигдаль. Сформуйте довгі батони.\n3. Випечіть батони до золотистого кольору (близько 25 хвилин).\n4. Дістаньте, наріжте по діагоналі на скибки і підсушіть їх у духовці ще 10 хвилин.'),
(39, 5, 'Профітролі з шоколадом', 'Маленькі кульки з кремовою начинкою.', 'img/profiteroles.jpg', 4, '1. Приготуйте класичне заварне тісто (як для еклерів).\n2. Відсадіть на деко маленькі кульки розміром з волоський горіх.\n3. Випікайте до золотистої скоринки і повного висихання всередині.\n4. Начиніть збитими вершками і рясно полийте шоколадним соусом.'),
(40, 3, 'Горішки зі згущеним молоком', 'Смак дитинства.', 'img/nuts_cookie.jpg', 4, '1. Розітріть м''яке масло з цукром та жовтками. Додайте борошно і гашену соду.\n2. Замісіть м''яке пісочне тісто.\n3. Відщипуйте маленькі шматочки тіста і випікайте у спеціальній формі-горішниці.\n4. Наповніть охолоджені половинки вареним згущеним молоком і з''єднайте.'),
(41, 5, 'Капкейки "Орео"', 'Шоколадні мафіни з кремом на основі печива.', 'img/oreo_cupcakes.jpg', 7, '1. Змішайте сухі інгредієнти (какао, борошно, цукор) з вологими (яйця, молоко, масло).\n2. Додайте в тісто поламані шматочки печива Орео і випікайте у формочках.\n3. Збийте крем-сир з маслом та пудрою, додайте дрібну крихту печива.\n4. Відсадіть крем шапочкою на охолоджені капкейки.'),
(42, 5, 'Фруктовий тарт', 'Пісочна основа з заварним кремом та свіжими фруктами.', 'img/fruit_tart.jpg', 22, '1. Замісіть рублене пісочне тісто, розподіліть по формі для тарта і випечіть з вантажем.\n2. Зваріть класичний крем патісьєр (заварний на жовтках з молоком).\n3. Викладіть холодний крем у випечену і охолоджену основу.\n4. Прикрасьте зверху великою кількістю свіжих ягід та фруктів.'),
(43, 3, 'Шоколадне печиво з тріщинками', 'Красиве та дуже смачне печиво.', 'img/cracked_cookies.jpg', 8, '1. Розтопіть шоколад з маслом. Збийте яйця з цукром.\n2. З''єднайте маси, додайте борошно з какао і розпушувачем. Охолодіть тісто в холодильнику.\n3. Скатайте кульки і дуже щедро обваляйте їх у цукровій пудрі.\n4. Випікайте 10-12 хвилин при 180°C. Печиво розтріскається і стане красивим.'),
(44, 5, 'Трюфелі ручної роботи', 'Цукерки з якісного шоколаду та вершків.', 'img/truffles.jpg', 3, '1. Нагрійте жирні вершки майже до кипіння.\n2. Вилийте гарячі вершки на подрібнений чорний шоколад. Додайте шматочок масла і перемішайте.\n3. Накрийте ганаш плівкою в контакт і охолодіть мінімум 4 години.\n4. Скатайте кульки і обваляйте їх у гіркому какао-порошку.'),
(45, 5, 'Зефір яблучний', 'Натуральний домашній зефір на агарі.', 'img/zefir.jpg', 6, '1. Запечіть яблука і перетріть у густе пюре. Збийте пюре з білком до пишності.\n2. Зваріть сироп з цукру, води та агар-агару до 110°C.\n3. Не припиняючи збивати, влийте гарячий сироп у білково-яблучну масу.\n4. Швидко відсадіть половинки зефіру і залиште стабілізуватися на 12-24 години.'),
(46, 5, 'Панна котта з полуницею', 'Вершкове желе з ягідним соусом.', 'img/panna_cotta.jpg', 10, '1. Замочіть желатин у холодній воді.\n2. Нагрійте вершки з молоком та цукром (не кип''ятіть!). Введіть набряклий желатин.\n3. Розлийте масу по формах або келихах і поставте в холодильник до застигання.\n4. Зверху викладіть пюре зі свіжої полуниці з пудрою.'),
(47, 3, 'Віденське печиво', 'Тертий пиріг у форматі печива з варенням.', 'img/vienna_cookies.jpg', 10, '1. Розітріть масло з цукром та борошном до стану крихти (або замісіть тісто і заморозьте частину).\n2. Викладіть більшу частину тіста на деко і злегка притисніть.\n3. Намажте шаром густого кислого варення (смородина або слива).\n4. Зверху засипте залишками крихти і випікайте до золотистого кольору. Наріжте гарячим.'),
(48, 5, 'Трубочки з білковим кремом', 'Хрустке тісто та невагомий крем.', 'img/cream_rolls.jpg', 15, '1. Наріжте готове листкове тісто довгими смужками.\n2. Накрутіть смужки на спеціальні металеві конуси внапух і випечіть до золотистості.\n3. Зваріть цукровий сироп і влийте його у збиті білки (італійська меренга).\n4. Начиніть охолоджені трубочки кремом за допомогою кондитерського мішка.'),
(49, 1, 'Вафельний торт', 'Класика з вареною згущенкою та горіхами.', 'img/waffle_cake.jpg', 24, '1. Збийте м''яке вершкове масло міксером до побіління.\n2. Поступово додавайте варене згущене молоко, продовжуючи збивати крем.\n3. Перемажте готові хрусткі вафельні коржі цим кремом.\n4. Кожен шар (або через один) посипайте подрібненими горіхами. Дайте настоятись.'),
(50, 5, 'Штрудель яблучний', 'Тонке витяжне тісто з яблуками та корицею.', 'img/strudel.jpg', 30, '1. Замісіть еластичне тісто з борошна, води і олії. Дайте йому відпочити.\n2. Наріжте яблука, змішайте з цукром, корицею та родзинками.\n3. Розтягніть тісто на рушнику до стану паперу, змажте маслом і викладіть начинку.\n4. Згорніть за допомогою рушника у рулет і запікайте до хрусткої скоринки.');
